        await using var tx = await conn.BeginTransactionAsync(cancellationToken);

        var now = DateTimeOffset.UtcNow;
        var sql = @"
            SELECT JobId, JobTypeId, SerializedPayload, SerializedContext, Status, AttemptCount, NextExecutionTime, CreatedAt, StartedAt, CompletedAt, FailureErrorMessage, FailureStackTrace, FailedAt
            FROM SystemCellJobs
            WHERE Status = @QueuedStatus AND (NextExecutionTime IS NULL OR NextExecutionTime <= @Now)
            ORDER BY NextExecutionTime ASC NULLS FIRST, CreatedAt ASC
