        var cmd = new NpgsqlCommand(sql, conn) { Transaction = tx };
        cmd.Parameters.AddWithValue("QueuedStatus", (int)JobStatus.Queued);
        cmd.Parameters.AddWithValue("Now", now);

        using var reader = await cmd.ExecuteReaderAsync(cancellationToken);
