        await reader.CloseAsync();

        var updateSql = @"
            UPDATE SystemCellJobs 
            SET Status = @StartedStatus, AttemptCount = AttemptCount + 1, StartedAt = @Now
            WHERE JobId = @JobId";

        var updateCmd = new NpgsqlCommand(updateSql, conn) { Transaction = tx };
        updateCmd.Parameters.AddWithValue("StartedStatus", (int)JobStatus.Started);
        updateCmd.Parameters.AddWithValue("Now", now);
        updateCmd.Parameters.AddWithValue("JobId", jobId);

        await updateCmd.ExecuteNonQueryAsync(cancellationToken);
        await tx.CommitAsync(cancellationToken);

        return new EnqueuedJob(jobId, jobTypeId, payload, context, JobStatus.Started, attemptCount, nextExecutionTime, created, now, null, null);
    }

